"use strict";
let planetDirectoryReady=false,planetDirectoryEditable=false,planetDirectoryRevision=0,planetDirectoryBaseline='',planetDirectorySaving=false,planetDirectoryApplying=false,planetDirectoryTimer;
function canonicalDirectory(value){if(Array.isArray(value))return value.map(canonicalDirectory);if(value&&typeof value==='object')return Object.fromEntries(Object.keys(value).sort().filter(k=>value[k]!==undefined).map(k=>[k,canonicalDirectory(value[k])]));return value;}
function directorySnapshot(){const planets=state.galaxy.map(p=>({...p,publicValue:p.player?playerValue():npcValue(p),publicScore:planetScore(p)})).sort((a,b)=>a.id.localeCompare(b.id));const structures=copy(state.structurePlanets).sort((a,b)=>a.id.localeCompare(b.id));const profiles=new Map([...(state.allianceDirectory||[]),state.alliance].map(a=>[a.name,a]));const alliances=[...profiles.values()].map(a=>{const v=copy(a);for(const key of ['intelRecords','intelBrowserCoords','intelTarget','intelSearch','intelGalaxyScans'])delete v[key];return v;}).sort((a,b)=>a.name.localeCompare(b.name));return {planets,structures,alliances};}
async function centralDirectoryRequest(path,body,method){const response=await fetch(path,{credentials:'same-origin',method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok){const error=Error(result.error||'The central database is unavailable.');error.status=response.status;throw error;}return result;}
function directoryStatus(message){for(const id of ['centralPlanetStatus','intelDirectoryStatus']){const el=document.getElementById(id);if(el)el.textContent=message;}}
function applySharedDirectory(data){planetDirectoryApplying=true;const generation=data.resetGeneration||0;const changedUser=!!data.userId&&state.centralPlayerId!==data.userId&&(!data.canEdit||!!state.centralPlayerId);if(generation!==(state.centralResetGeneration||0)||changedUser){state=freshState();if(typeof midayLastSync!=='undefined')midayLastSync='';}state.centralResetGeneration=generation;state.centralPlayerId=data.userId;const own=data.planets.find(p=>p.player),oldOwn=state.galaxy.find(p=>p.player);state.race=state.race||own?.race||'Terran';for(const slot of ['base','f1','f2','f3'])state.fleets[slot]=normalizeFleet(state.fleets[slot]||{});state.ships=normalizeFleet(state.ships||{});state.galaxy=data.planets;if(!own&&oldOwn&&!state.galaxy.some(p=>p.id===oldOwn.id))state.galaxy.push(oldOwn);state.structurePlanets=data.structures;const myPlanet=own||oldOwn,profile=data.alliances.find(a=>a.name===myPlanet?.alliance);if(profile){const ui={intelBrowserCoords:state.alliance.intelBrowserCoords,intelTarget:state.alliance.intelTarget,intelSearch:state.alliance.intelSearch};const oldRecords=state.alliance.name===profile.name?state.alliance.intelRecords:{};state.alliance={...copy(freshState().alliance),...profile,...ui,intelRecords:oldRecords||{}};}state.allianceDirectory=data.alliances.filter(a=>a.name!==state.alliance.name);planetDirectoryRevision=data.revision;planetDirectoryEditable=data.canEdit;planetDirectoryReady=true;update();planetDirectoryBaseline=JSON.stringify(canonicalDirectory(directorySnapshot()));planetDirectoryApplying=false;directoryStatus('CENTRAL PLANET DATABASE · CONNECTED');}
async function initializePlanetDirectory(){try{const data=await centralDirectoryRequest('/api/planets');planetDirectoryRevision=data.revision;planetDirectoryEditable=data.canEdit;if(!data.planets.length){if(!data.canEdit){directoryStatus('Waiting for the administrator to publish the planet directory.');return;}const snapshot=directorySnapshot(),saved=await centralDirectoryRequest('/api/planets',{revision:data.revision,...snapshot});planetDirectoryRevision=saved.revision;planetDirectoryReady=true;planetDirectoryBaseline=JSON.stringify(canonicalDirectory(snapshot));directoryStatus('CENTRAL PLANET DATABASE · CURRENT PLANETS IMPORTED');const notes=Object.entries(state.alliance.intelRecords||{}).map(([coords,r])=>({coords,status:r.status||'Unassessed',note:r.note||'',tick:r.tick||state.tick}));if(notes.length)await centralDirectoryRequest('/api/alliance-intel',{records:notes});update();return;}applySharedDirectory(data);}catch(error){directoryStatus(error.message+' · local round preserved');}}
function queuePlanetDirectorySync(){if(!planetDirectoryReady||!planetDirectoryEditable||planetDirectoryApplying)return;clearTimeout(planetDirectoryTimer);planetDirectoryTimer=setTimeout(syncPlanetDirectory,750);}
async function syncPlanetDirectory(){if(planetDirectorySaving||!planetDirectoryReady||!planetDirectoryEditable||planetDirectoryApplying)return;const snapshot=directorySnapshot(),encoded=JSON.stringify(canonicalDirectory(snapshot));if(encoded===planetDirectoryBaseline)return;planetDirectorySaving=true;try{const saved=await centralDirectoryRequest('/api/planets',{revision:planetDirectoryRevision,...snapshot});planetDirectoryRevision=saved.revision;planetDirectoryBaseline=encoded;directoryStatus('CENTRAL PLANET DATABASE · SAVED');}catch(error){directoryStatus(error.message);if(error.status===409){const latest=await centralDirectoryRequest('/api/planets');applySharedDirectory(latest);notify('Another session updated the planet directory. The latest shared planets were loaded.',true);}}finally{planetDirectorySaving=false;}}
async function persistAllianceSettings(settings){if(!planetDirectoryReady)return;await syncPlanetDirectory();const data=await centralDirectoryRequest('/api/alliance-settings',{revision:planetDirectoryRevision,...settings});planetDirectoryRevision=data.revision;}
async function refreshSharedPlanets(){if(!planetDirectoryReady||planetDirectorySaving)return;try{const data=await centralDirectoryRequest('/api/planets');if(data.revision!==planetDirectoryRevision){const dirty=JSON.stringify(canonicalDirectory(directorySnapshot()))!==planetDirectoryBaseline;if(dirty&&planetDirectoryEditable){await syncPlanetDirectory();return;}applySharedDirectory(data);}}catch(error){directoryStatus(error.message);}}
initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);

setInterval(async()=>{try{const data=await centralDirectoryRequest('/api/version');const button=document.getElementById('versionReload');if(button&&data.version!=='0.64.0')button.hidden=false;}catch{}},60000);document.addEventListener('click',e=>{if(e.target.id==='versionReload')location.reload();});
